"content": "#include "./SYSTEM/usart/usart.h"
#include "stm32f1xx_hal.h"
#include "./SYSTEM/sys/sys.h"
#include "./BSP/LED/led.h"
#include "jsonrpc_handler.h"
#include "d601_lcd.h"
#include "d601_arm2d_demo.h"
#include "d601_gpio.h"

int main(void)
{
 SystemCoreClockUpdate();
 sys_stm32_clock_init(9);
 HAL_Init();
 led_init();
 usart_init(115200);
 printf("\r\n[D601-F103] device-pod LCD bring-up\r\n");

 d601_lcd_init();
 d601_gpio_init();
 d601_arm2d_demo_show();
 printf("[D601-F103] LCD ID=0x%04X\r\n"...
exitCode=0

